using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Security.Claims;
using MediaBrowser.Controller.Library;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Campground.Shared.Security
{
    /// <summary>Who's calling, and may they see this item. Parental controls always apply (rule 9).</summary>
    internal static class AccessChecks
    {
        /// <summary>Jellyfin's user-id claim.</summary>
        internal const string UserIdClaim = "Jellyfin-UserId";

        /// <summary>Jellyfin's admin role.</summary>
        internal const string AdministratorRole = "Administrator";

        /// <summary>The calling user's id, or null for anonymous / API-key calls.</summary>
        internal static Guid? UserId(ClaimsPrincipal? principal)
        {
            var value = principal?.FindFirst(UserIdClaim)?.Value;
            return Guid.TryParse(value, out var id) && id != Guid.Empty ? id : null;
        }

        /// <summary>True when the caller is a Jellyfin administrator.</summary>
        internal static bool IsAdministrator(ClaimsPrincipal? principal) => principal?.IsInRole(AdministratorRole) ?? false;

        /// <summary>True when the caller is the given user, or an administrator.</summary>
        internal static bool IsSelfOrAdmin(ClaimsPrincipal? principal, Guid userId)
            => IsAdministrator(principal) || UserId(principal) == userId;

        /// <summary>
        /// True when the user may see the item — library access, parental rating, tags, schedules — using
        /// Jellyfin's own check. False for unknown users or items. Never bypass this for "convenience".
        /// </summary>
        internal static bool CanSee(IUserManager users, ILibraryManager library, Guid userId, Guid itemId)
        {
            var user = users.GetUserById(userId);
            if (user == null)
            {
                return false;
            }

            var item = library.GetItemById(itemId);
            return item != null && item.IsVisible(user);
        }
    }

    /// <summary>One controller action reachable without signing in.</summary>
    internal sealed record AnonymousRoute(string Controller, string Action, string Route);

    /// <summary>
    /// Lists every action in an assembly that can be called anonymously, so plugin tests can assert the list
    /// equals an explicit allow-list. An action is anonymous when it (or its controller) has
    /// [AllowAnonymous], or when neither has any [Authorize].
    /// </summary>
    internal static class AnonymousRouteAudit
    {
        internal static IReadOnlyList<AnonymousRoute> Find(Assembly assembly)
        {
            var result = new List<AnonymousRoute>();
            var mvc = typeof(ControllerBase).Assembly;
            foreach (var type in SafeTypes(assembly).Where(t => !t.IsAbstract && typeof(ControllerBase).IsAssignableFrom(t)))
            {
                var classAuth = type.GetCustomAttributes<AuthorizeAttribute>(true).Any();
                var classAnon = type.GetCustomAttributes<AllowAnonymousAttribute>(true).Any();
                var prefix = type.GetCustomAttribute<RouteAttribute>(true)?.Template ?? string.Empty;
                // Inherited actions count; ControllerBase's own members (and object's) are not actions.
                foreach (var m in type.GetMethods(BindingFlags.Public | BindingFlags.Instance))
                {
                    if (m.DeclaringType == typeof(object) || m.DeclaringType?.Assembly == mvc)
                    {
                        continue;
                    }

                    if (m.IsSpecialName || m.GetCustomAttribute<NonActionAttribute>() != null)
                    {
                        continue;
                    }

                    var methodAuth = m.GetCustomAttributes<AuthorizeAttribute>(true).Any();
                    var methodAnon = m.GetCustomAttributes<AllowAnonymousAttribute>(true).Any();
                    if (methodAnon || classAnon || (!methodAuth && !classAuth))
                    {
                        var template = m.GetCustomAttributes<Microsoft.AspNetCore.Mvc.Routing.HttpMethodAttribute>(true)
                            .Select(a => a.Template).FirstOrDefault(t => t != null) ?? string.Empty;
                        result.Add(new AnonymousRoute(type.Name, m.Name, (prefix + "/" + template).Trim('/')));
                    }
                }
            }

            return result.OrderBy(r => r.Controller).ThenBy(r => r.Action).ToList();
        }

        private static IEnumerable<Type> SafeTypes(Assembly a)
        {
            try
            {
                return a.GetTypes();
            }
            catch (ReflectionTypeLoadException e)
            {
                return e.Types.OfType<Type>();
            }
        }
    }
